    counts = {}
    scales = []
    for item in history:
        if item == 0:
            scales.append(0.0)
            continue
        earlier = counts.get(item, 0)
        scales.append(1.0 + 0.1 * min(math.log1p(earlier), 2.0))
        counts[item] = earlier + 1
    result = np.zeros(maxlen, dtype=np.float32)
    retained = scales[-maxlen:]
    if retained:
        result[-len(retained):] = retained
    return result


